function parseRows(text, difficulty, start) {
  return text.trim().split('\n').filter(Boolean).map((row, index) => {
    const [title, category, task, io, example, approach, complexity] = row.split('|')
    return {id: start + index, difficulty, title, category, task, io, example, approach, complexity}
  })
}

